def _ledger_init(pg, prefix):
    path = prefix + "_ledger.json"
    if os.path.exists(path):
        led = json.load(open(path))
    else:
        led = {"groups": [{"name": g.get("name"), "n_params": int(sum(p.numel() for p in g["params"])), "first_open_epoch": None, "epochs_open": 0,
                           "grad_steps": 0, "lr_first": None, "lr_last": None, "lr_sum": 0.0} for g in pg], "epochs_seen": []}
    led["_path"] = path
    return led


def _ledger_epoch(led, pg, ep):
    if ep + 1 in led["epochs_seen"]:
        return
